	if err := validateBuiltSearchSnapshot(snapshot, repositoryKey, providerVersion, tree, options); err != nil {
		return ProviderSnapshot{}, false, fmt.Errorf(
			"preindex snapshot provenance mismatch for commit %q tree %q: %w",
			commit, tree, err,
		)
	}
