		remove:       (*os.Root).Remove,
	}
	if root := cache.Snapshot.Header.RepoRoot; root != "" {
		if _, tree, err := resolveCommittedHEAD(ctx, root); err == nil {
			retention.protectTree = tree
		}
	}
	return retention, true
}

